    for char in paren_string:
        if char == '(':
            if temp:
                result.append(temp)
                temp = ""
            temp += '('
        elif char == ')':
            if temp:
                temp += ')'
                if temp == "()":
                    result.append(temp)
                    temp = ""
                else:
                    result.append(temp[1:-1])
                    temp = ""
        elif char == ' ':
            continue
