def max_product(num_str: str, N: int, K: int) -> int:
    if len(num_str) < N * K:
        raise ValueError("The length of the number string must be at least N * K.")
    if K < 0:
        raise ValueError("The number of multiplication signs must be non-negative.")

    max_num = 1
    for i in range(N):
        max_num *= int(num_str[i])

    max_product = max_num
    for i in range(N):
        new_num = int(num_str[i] + '0' * K) if i != N - 1 else 1
        multi_num = max_product / max_num * new_num
        max_product = max(max_product, multi_num)

    return int(max_product)

