            pass
        else:
            return "Invalid ISBN format. Expected a digit or 'X' as the last digit."
        isbn = isbn.replace("-", "")
        if isbn.isdigit():
            total = 0
            for i in range(len(isbn)):
                if i == len(isbn) - 1:
                    total += int(isbn[i]) * 10
                else:
                    total += int(isbn[i]) * (10 - i)
            remainder = total % 11
            if remainder == 0:
                return "Right"
            elif remainder == 1:
                return isbn.replace("-", "-X")
            else:
                return isbn.replace("-", "-" + str(11 - remainder))
        else:
            return "Invalid ISBN format. All digits should be valid."
    elif len(isbn) == 13:
        if isbn[0] == "9":
            pass
        else:
            return "Invalid ISBN format. Expected '9' at the start."
        isbn = isbn.replace("-", "")
        if isbn.isdigit():
            total = 0
            for i in range(len(isbn)):
                total += int(isbn[i]) * ((13 - i) % 2 + 2)
            remainder = total % 10
            if remainder == 0:
                return "Right"
            else:
                return isbn.replace("-", "-" + str(10 - remainder))
        else:
            return "Invalid ISBN format. All digits should be valid."
    else:
        return "Invalid ISBN format. Expected either 10 or 13 digits."

