    # Try placing aisles horizontally
    for i in range(M+1):
        col_counts = [0] * (N+1)
        for j in range(N):
            col_counts[j+1] = col_counts[j+1-1] + pair_counts[i][j+1-1]

        optimal_cols = []
        for col in range(1, N+1):
            if col_counts[col] == D:
                optimal_cols.append(col)

        if optimal_cols:
            # Return first column to minimize the amount of chatting
            return str(1), ' '.join(map(str, optimal_cols))

    # Try placing aisles vertically
    for j in range(N+1):
        row_counts = [0] * (M+1)
        for i in range(M):
            row_counts[i+1] = row_counts[i+1-1] + pair_counts[i+1][j]

        optimal_rows = []
        for row in range(1, M+1):
            if row_counts[row] == D:
                optimal_rows.append(row)

