def max_energy(beads):
    """
    Calculate the maximum energy that can be released by merging beads on a necklace.

    Args:
        beads: A list of integers where each integer represents the head value of a bead and
               the tail value of the previous bead. The tail value of the last bead is assumed
               to match the head value of the first bead due to the circular nature of the necklace.

    Returns:
        An integer representing the maximum energy that can be obtained by optimally merging all beads.

    Examples:
        >>> max_energy([2, 3, 5, 10])
        710
        >>> max_energy([1, 2, 3, 4])
        48
    """
    def dp(i, j):
        if i == j:
            return beads[i]
        if dp(i + 1, j) > dp(i, j - 1) and beads[i] == beads[j - 1]:
            return dp(i + 1, j) * beads[i]
        else:
            return dp(i, j - 1)

    return max(dp(i, n) + dp(i + 1, j) * beads[i] for i in range(n) for j in range(i + 1, n) if beads[i] == beads[j])

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n <= 0:
        return ""

    def format_term(coeff: int, degree: int) -> str:
        if coeff == 0:
            return ""

        sign = "-" if coeff < 0 else ""
        coefficient = abs(coeff)

        if coefficient == 1:
            part = ""
        else:
            part = f"{coefficient}"

        if degree == 0:
            part = "1"
        elif degree == 1:
            part = "x"
        else:
            part = "x^{}".format(degree)

        if sign and part:
            part = f"{sign}{part}"
        else:
            part = part if sign else ""

        return part

    result = ""
    for i in range(n, -1, -1):
        term = format_term(coeffs[i], i)
        if term:
            if result:
                result += " + "
            result += term

    return result

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    encoding_map = {}
    for encoded_char, original_char in zip(encoded, original):
        if original_char in encoding_map:
            if encoding_map[original_char] != encoded_char:
                return "Failed"
        else:
            encoding_map[original_char] = encoded_char

    decoded_chars = []
    missing = set(original)
    for char in message:
        if char in encoding_map:
            decoded_chars.append(encoding_map[char])
            missing.remove(char)
        else:
            return "Failed"

    if len(missing) != 0:
        return "Failed"

    return ''.join(decoded_chars)

import math

def largest_prime_factor(n: int) -> int:
    # Base case: 1 is neither prime nor composite
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")

    # Divide n by 2 until it's odd
    while n % 2 == 0:
        n //= 2

    # n must be odd at this point, so we can skip one element (Note i = i + 2)
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        # While i divides n, divide n by i
        while n % i == 0:
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or n - k * x + 1 < k:
        return 0

    def count_partitions_helper(start, remain, parts):
        if parts == k:
            return remain == 0
        if start > n or remain < 0:
            return 0
        n_ways = 0
        for i in range(start, n // x + 1):
            n_ways += count_partitions_helper(i + 1, remain - x * i, parts + 1)
        return n_ways

    return count_partitions_helper(1, n, 1)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n < 1 or last < 0 or (last + 1) > n:
        return 0
    if (n, last) in memo:
        return memo[(n, last)]
    if last == 1:
        return 1
    count = 0
    for i in range(1, last + 1):
        if i <= n // 2 and count_sequences(n, i, memo) > 0:
            count += 1
    memo[(n, last)] = count
    return count

