def generate_numbers(n, rules) -> int:
    if not rules or not n or not isinstance(n, int) or not isinstance(rules, list):
        raise ValueError("Invalid input")

    # Store numbers in set to ensure uniqueness
    seen = set()
    queue = deque([n])
    seen.add(n)

    transformations = {x: y for x, y in rules}

    while queue:
        current_number = queue.popleft()
        for i in range(9):
            next_digit = transformations.get(i, i)
            next_number = next_number if next_digit != current_number else n
            if next_number not in seen:
                seen.add(next_number)
                queue.append(next_number)

    return len(seen)

