def vigenere_decrypt(key: str, ciphertext: str) -> str:
    # Validate input types
    if not all(c.isalpha() for c in key) or not all(c.isalpha() for c in ciphertext):
        raise ValueError("Key and ciphertext must contain only alphabetic characters.")

    # Normalize the key and ciphertext
    key = key.upper()
    ciphertext = ciphertext.upper()

    decrypted = ""
    key_index = 0

    for char in ciphertext:
        if char.isalpha():
            shift_amount = ord(key[key_index]) - ord('A')
            if char.isupper():
                decrypted += chr((ord(char) - ord('A') - shift_amount) % 26 + ord('A'))
            else:
                decrypted += chr((ord(char) - ord('a') - shift_amount) % 26 + ord('a'))
            key_index = (key_index + 1) % len(key)
    return decrypted

