def minimum_students_to_leave(heights: List[int]) -> int:
    if not heights:
        return 0

    start_index = 0
    end_index = len(heights) - 1

    left_count = 0
    right_count = 0

    while start_index < end_index:
        if heights[start_index] < heights[start_index + 1]:
            left_count += 1
        elif heights[start_index] > heights[start_index + 1]:
            left_count -= 1

        if heights[end_index] < heights[end_index - 1]:
            right_count += 1
        elif heights[end_index] > heights[end_index - 1]:
            right_count -= 1

        start_index += 1
        end_index -= 1

    return min(left_count, right_count)

